import { defineSchema, lazySchema } from "../../schemas/index.js";
import { isUuid, toConversationPartsFromUiMessage } from "../../chat/conversation.js";
import { INPUT_VALIDATION_FAILED, INVALID_ARGUMENT, NETWORK_ERROR, TIMEOUT_ERROR, } from "../../errors/index.js";
const CONVERSATION_API_TIMEOUT_MS = 15_000;
/** Zod schema for get conversation record. */
export const getConversationRecordSchema = defineSchema((v) => v.object({
    id: v.string(),
    projectId: v.string().nullable().optional(),
    project_id: v.string().nullable().optional(),
})
    .passthrough()
    .transform((data) => {
    const d = data;
    return {
        id: d.id,
        projectId: d.projectId ??
            d.project_id ?? null,
    };
}));
/** Schema for conversation record.
 * @deprecated Use getConversationRecordSchema()
 */
export const ConversationRecordSchema = lazySchema(getConversationRecordSchema);
/** Zod schema for get conversation message record. */
export const getConversationMessageRecordSchema = defineSchema((v) => v.object({
    id: v.string().uuid(),
}));
/** Schema for conversation message record.
 * @deprecated Use getConversationMessageRecordSchema()
 */
export const ConversationMessageRecordSchema = lazySchema(getConversationMessageRecordSchema);
async function controlPlaneJson(input) {
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), CONVERSATION_API_TIMEOUT_MS);
    let response;
    try {
        response = await fetch(input.url, {
            method: input.method ?? "GET",
            headers: {
                Authorization: `Bearer ${input.authToken}`,
                "Content-Type": "application/json",
            },
            ...(input.body !== undefined ? { body: JSON.stringify(input.body) } : {}),
            signal: controller.signal,
        });
    }
    catch (error) {
        if (error instanceof DOMException && error.name === "AbortError") {
            throw TIMEOUT_ERROR.create({
                detail: `${input.operation} timed out after ${CONVERSATION_API_TIMEOUT_MS}ms`,
            });
        }
        throw error;
    }
    finally {
        clearTimeout(timeout);
    }
    if (!response.ok) {
        const body = await response.text().catch(() => "");
        input.onResponseError?.({
            status: response.status,
            statusText: response.statusText,
            body,
        });
        throw NETWORK_ERROR.create({
            detail: `${input.operation} failed (${response.status}): ${body || response.statusText}`,
        });
    }
    return input.responseSchema.parse(await response.json());
}
function buildConversationPath(apiUrl, conversationId) {
    return `${apiUrl}/conversations/${conversationId}`;
}
function buildConversationMessagesPath(apiUrl, conversationId) {
    return `${buildConversationPath(apiUrl, conversationId)}/messages`;
}
async function requestConversationRecord(input) {
    return controlPlaneJson({
        authToken: input.authToken,
        url: buildConversationPath(input.apiUrl, input.conversationId),
        responseSchema: ConversationRecordSchema,
        operation: "Fetch conversation",
    });
}
/**
 * Deprecated. Use `Conversation.get` from `veryfront/conversations`. Fetches a conversation
 * record.
 * @deprecated Use `Conversation.get` from `veryfront/conversations`.
 */
export async function fetchConversationRecord(input) {
    return requestConversationRecord(input);
}
/** Ensure conversation project link helper. */
export async function ensureConversationProjectLink(input) {
    const conversation = await requestConversationRecord(input);
    if (conversation.projectId === input.projectId)
        return;
    if (conversation.projectId !== null) {
        throw INVALID_ARGUMENT.create({
            detail: `Conversation ${input.conversationId} is already linked to a different project (${conversation.projectId})`,
        });
    }
    await controlPlaneJson({
        authToken: input.authToken,
        url: buildConversationPath(input.apiUrl, input.conversationId),
        method: "PATCH",
        body: { project_reference: input.projectId },
        responseSchema: ConversationRecordSchema,
        operation: "Link conversation to project",
    });
}
/**
 * Forwards the caller's body unchanged to `POST /conversations`, the route of
 * `Conversation.create`.
 */
async function requestCreateConversationRecord(input) {
    return controlPlaneJson({
        authToken: input.authToken,
        url: `${input.apiUrl}/conversations`,
        method: "POST",
        body: input.body,
        responseSchema: ConversationRecordSchema,
        operation: "Create conversation",
    });
}
/**
 * Deprecated. Use `Conversation.create` from `veryfront/conversations`. Creates a
 * conversation record from an untyped request body.
 * @deprecated Use `Conversation.create` from `veryfront/conversations`.
 */
export async function createConversationRecord(input) {
    return requestCreateConversationRecord(input);
}
/**
 * Forwards the caller's body unchanged to `POST /conversations/{conversation_id}/messages`,
 * the route of `conversation.createMessage`.
 */
async function requestCreateConversationMessage(input) {
    return controlPlaneJson({
        authToken: input.authToken,
        url: buildConversationMessagesPath(input.apiUrl, input.conversationId),
        method: "POST",
        body: input.body,
        responseSchema: ConversationMessageRecordSchema,
        operation: input.operation ?? "Create conversation message",
        onResponseError: input.onResponseError,
    });
}
/**
 * Deprecated. Use `conversation.createMessage` from `veryfront/conversations`. Creates a
 * conversation message from an untyped request body.
 * @deprecated Use `conversation.createMessage` from `veryfront/conversations`.
 */
export async function createConversationMessage(input) {
    return requestCreateConversationMessage(input);
}
/** Message shape for persist conversation user. */
export async function persistConversationUserMessage(input) {
    const parts = toConversationPartsFromUiMessage(input.message);
    if (parts.length === 0) {
        throw INPUT_VALIDATION_FAILED.create({
            detail: "CONVERSATION_USER_MESSAGE_REQUIRES_PERSISTABLE_PARTS",
        });
    }
    return requestCreateConversationMessage({
        authToken: input.authToken,
        apiUrl: input.apiUrl,
        conversationId: input.conversationId,
        operation: input.operation ?? "Persist conversation user message",
        body: {
            role: "user",
            parts,
            idempotency_key: input.message.id,
            ...(isUuid(input.parentMessageId) ? { parent_id: input.parentMessageId } : {}),
            ...(input.message.metadata ? { metadata: input.message.metadata } : {}),
        },
        onResponseError: (error) => {
            input.onFailure?.({
                conversationId: input.conversationId,
                messageId: input.message.id,
                ...error,
            });
        },
    });
}
/** Context for find latest user conversation message. */
export function findLatestUserConversationMessageContext(messages) {
    const latestUserMessageIndex = messages.findLastIndex((message) => message.role === "user");
    const latestUserMessage = latestUserMessageIndex >= 0
        ? messages[latestUserMessageIndex]
        : undefined;
    if (latestUserMessageIndex >= 0) {
        for (let index = latestUserMessageIndex - 1; index >= 0; index -= 1) {
            const message = messages[index];
            if (message && message.role !== "system") {
                return {
                    latestUserMessage,
                    visibleParentMessageId: message.id,
                };
            }
        }
    }
    return {
        latestUserMessage,
    };
}
/** Message shape for persist latest conversation user. */
export async function persistLatestConversationUserMessage(input) {
    if (!input.enabled || !input.conversationId) {
        return;
    }
    const { latestUserMessage, visibleParentMessageId } = findLatestUserConversationMessageContext(input.messages);
    if (!latestUserMessage) {
        throw INPUT_VALIDATION_FAILED.create({
            detail: input.missingUserMessageErrorMessage ?? "CONVERSATION_REQUIRES_USER_MESSAGE",
        });
    }
    await persistConversationUserMessage({
        authToken: input.authToken,
        apiUrl: input.apiUrl,
        conversationId: input.conversationId,
        message: latestUserMessage,
        operation: input.operation,
        ...(isUuid(visibleParentMessageId) ? { parentMessageId: visibleParentMessageId } : {}),
        ...(input.onFailure ? { onFailure: input.onFailure } : {}),
    });
}
/** Bootstrap conversation agent run helper. */
export async function bootstrapConversationAgentRun(input) {
    // Standalone self-admission was removed. Fail before any conversation or
    // message write so a missing capability cannot leave an orphaned handoff.
    const admitRun = input.admitRun;
    if (!admitRun) {
        throw new Error("Conversation-backed run bootstrap requires the bound admission capability");
    }
    if (input.parentConversationId && input.ensureProjectId) {
        await ensureConversationProjectLink({
            authToken: input.authToken,
            apiUrl: input.apiUrl,
            conversationId: input.parentConversationId,
            projectId: input.ensureProjectId,
        });
    }
    const conversation = await requestCreateConversationRecord({
        authToken: input.authToken,
        apiUrl: input.apiUrl,
        body: input.conversationBody,
    });
    const effectiveProjectId = input.projectId ?? conversation.projectId;
    const message = await requestCreateConversationMessage({
        authToken: input.authToken,
        apiUrl: input.apiUrl,
        conversationId: conversation.id,
        body: input.handoffMessageBody,
    });
    const run = await admitRun({
        authToken: input.authToken,
        apiUrl: input.apiUrl,
        conversationId: conversation.id,
        runId: input.runId,
        parentRunId: input.parentRunId,
        agentId: input.agentId,
        implementationKind: input.implementationKind,
        projectId: effectiveProjectId,
        runtimeTargetKind: input.runtimeTargetKind,
        runtimeTargetEnvironmentId: input.runtimeTargetEnvironmentId,
        branchId: input.branchId,
    });
    return { conversation, message, run };
}
